update public.raffle_numbers set status='confirmed' where raffle_id=(select id from public.raffles where slug='iphone-16-pro') and number in (12,23); update public.raffle_numbers set status='pending' where raffle_id=(select id from public.raffles where slug='iphone-16-pro') and number=34; update public.raffle_numbers set status='blocked',blocked_reason='Promocional' where raffle_id=(select id from public.raffles where slug='iphone-16-pro') and number=55;