insert into public.raffles (title,slug,description,prize_name,price_per_number,number_start,number_end,sales_close_at,draw_at,draw_method,status) values ('iPhone 16 Pro','iphone-16-pro','Un iPhone 16 Pro para llevar tus ideas más lejos.','iPhone 16 Pro 256 GB',10000,0,99,'2026-10-07T18:00:00-05:00','2026-10-07T20:00:00-05:00','Lotería de Medellín','active') on conflict (slug) do nothing;
insert into public.raffle_numbers (raffle_id,number,number_display) select r.id,n, lpad(n::text,2,'0') from public.raffles r cross join generate_series(0,99) n where r.slug='iphone-16-pro' on conflict do nothing;
